/**
 * Places the IAB `app-ads.txt` into the Android app's assets.
 *
 * The AdMob SDK reads `app-ads.txt` from the APK's
 * `assets/app-ads.txt`. The `android/` directory is generated by
 * `expo prebuild` on every build and is gitignored, so the file cannot
 * simply be committed there - it has to be written during prebuild.
 *
 * Skipping it causes significant revenue loss, because the file is how
 * the IAB identifies the seller (us) to the ad exchange, and without it
 * the traffic is not sellable at the right prices.
 *
 * The content follows the IAB format:
 *   <domain>, <seller ID>, <relationship type>, <certification ID>, <ad types>
 *
 * The seller id and certification id come from the AdMob console
 * (Account Management -> App information). AppLovin gets its own line
 * when AppLovin mediation is enabled - it is not yet, so only AdMob
 * (Google) is listed.
 */

const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('@expo/config-plugins');

const APP_ADS_TXT = [
  // domain, seller id, relationship, certification id, ad types
  'google.com, pub-3898064484524772, DIRECT, f08c47fec0942fa0ddf0,0',
  '',
].join('\n');

/**
 * @param {import('@expo/config-plugins').ExpoConfig} config
 */
function withAdMobAssets(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const assetsDir = path.join(
        cfg.modRequest.platformProjectRoot,
        'app',
        'src',
        'main',
        'assets',
      );
      await fs.promises.mkdir(assetsDir, { recursive: true });
      await fs.promises.writeFile(
        path.join(assetsDir, 'app-ads.txt'),
        APP_ADS_TXT,
        'utf8',
      );
      return cfg;
    },
  ]);
}

module.exports = withAdMobAssets;
module.exports.APP_ADS_TXT = APP_ADS_TXT;
